<script setup lang="ts">
const PAGE_SIZE=25
const tenantId=ref("");const identityId=ref("");const status=ref("");const offset=ref(0)
const query=computed(()=>({tenantId:tenantId.value||undefined,identityId:identityId.value||undefined,status:status.value||undefined,offset:String(offset.value),limit:String(PAGE_SIZE)}))
const {data,pending,error,refresh}=await useFetch<any>("/api/provider/memberships",{query})
watch([tenantId,identityId,status],()=>{offset.value=0})
</script>
<template><div class="page-stack"><div class="page-heading"><div><p class="eyebrow">MEMBERSHIP</p><h1>Memberships</h1><p>Provider administration across tenant relationships.</p></div><button class="secondary-button" @click="refresh()">Refresh</button></div><section class="panel"><div class="admin-filters admin-filters--three"><input v-model="tenantId" placeholder="Tenant ID"><input v-model="identityId" placeholder="Identity ID"><select v-model="status"><option value="">All statuses</option><option>pending</option><option>active</option><option>suspended</option><option>archived</option></select></div><div v-if="pending" class="loading-panel">Loading memberships…</div><div v-else-if="error" class="error-panel">{{error.message}}</div><div v-else-if="data?.items?.length" class="table-wrap"><table><thead><tr><th>Membership</th><th>Identity</th><th>Tenant</th><th>Type</th><th>Status</th></tr></thead><tbody><tr v-for="item in data.items" :key="item.membershipId"><td><NuxtLink class="table-link mono" :to="`/memberships/${item.membershipId}`">{{item.membershipId}}</NuxtLink></td><td class="mono">{{item.identityId}}</td><td class="mono">{{item.tenantId}}</td><td>{{item.membershipType}}</td><td><span class="pill" :class="{'pill--good':item.status==='active'}">{{item.status}}</span></td></tr></tbody></table></div><div v-else class="empty-state"><strong>No memberships found</strong></div><AppPagination :total="data?.total??0" :offset="offset" :limit="PAGE_SIZE" @change="offset=$event" /></section></div></template>
